import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

// Module-level Google Fonts loading (delayRender/continueRender handled internally)
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: interFamily } = loadInter();

// Decorative Grid Background Component
const GridBackground: React.FC<{ width: number; height: number; gridColor: string }> = ({ width, height, gridColor }) => {
  return (
    <div
      style={{
        position: "absolute",
        width: width * 6,
        height: height * 6,
        left: -width * 2.5,
        top: -height * 2.5,
        backgroundImage: `
          linear-gradient(to right, ${gridColor} 1.5px, transparent 1.5px),
          linear-gradient(to bottom, ${gridColor} 1.5px, transparent 1.5px)
        `,
        backgroundSize: "80px 80px",
        opacity: 0.12,
        pointerEvents: "none",
        transition: "none",
      }}
    />
  );
};

// Colored Glow Spheres for Cinematic Depth
const GlowBlob: React.FC<{ x: number; y: number; size: number; color: string; opacity: number }> = ({ x, y, size, color, opacity }) => {
  return (
    <div
      style={{
        position: "absolute",
        left: x - size / 2,
        top: y - size / 2,
        width: size,
        height: size,
        borderRadius: "50%",
        backgroundColor: color,
        filter: "blur(140px)",
        opacity: opacity,
        pointerEvents: "none",
        transition: "none",
      }}
    />
  );
};



export type KineticHookTextProps = Record<string, any>;

const KineticHookText: React.FC<KineticHookTextProps> = ({
  backgroundColor = "#0d0f12",
  transparentBackground = false,
  durationInSeconds = 9,
  textColor = "#ffffff",
  accentColor = "#00ffaa",
  gridColor = "#2a303c",
  fontSizeMultiplier = 1.0,
  enableWiggle = true,
  phrase1 = "I WANNA SAY",
  phrase2 = "SOMETHING",
  phrase3 = "THAT MIGHT SURPRISE",
  phrase4 = "A LOT OF",
  phrase5Line1 = "BANKING &",
  phrase5Line2 = "CREDIT UNION",
  phrase6 = "LEADERS.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Resolve transparent vs solid background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings: Segment transition triggers normalized against total duration
  const p2 = Math.floor(durationInFrames * 0.16);
  const p3 = Math.floor(durationInFrames * 0.33);
  const p4 = Math.floor(durationInFrames * 0.50);
  const p5 = Math.floor(durationInFrames * 0.67);
  const p6 = Math.floor(durationInFrames * 0.83);

  // Transitions: Camera travel drivers (Spring curves between steps)
  const s1 = spring({ frame: frame - p2, fps, config: { damping: 15, stiffness: 90 } });
  const s2 = spring({ frame: frame - p3, fps, config: { damping: 15, stiffness: 90 } });
  const s3 = spring({ frame: frame - p4, fps, config: { damping: 15, stiffness: 90 } });
  const s4 = spring({ frame: frame - p5, fps, config: { damping: 15, stiffness: 90 } });
  const s5 = spring({ frame: frame - p6, fps, config: { damping: 15, stiffness: 90 } });

  // Phrase Positions (Offsets from layout center)
  const x1 = 0;
  const y1 = 0;
  const scale1 = 1.0;
  const rot1 = 0;

  const x2 = width * 0.22;
  const y2 = -height * 0.18;
  const scale2 = 1.35;
  const rot2 = -5;

  const x3 = -width * 0.25;
  const y3 = height * 0.12;
  const scale3 = 1.25;
  const rot3 = 6;

  const x4 = -width * 0.05;
  const y4 = height * 0.52;
  const scale4 = 1.05;
  const rot4 = -4;

  const x5 = 0;
  const y5 = height * 1.05;
  const scale5 = 1.45;
  const rot5 = 4;

  const x6 = 0;
  const y6 = height * 1.62;
  const scale6 = 2.2;
  const rot6 = 0;

  // Chain position & scale values smoothly through transitions
  const x_1_to_2 = interpolate(s1, [0, 1], [x1, x2]);
  const y_1_to_2 = interpolate(s1, [0, 1], [y1, y2]);
  const scale_1_to_2 = interpolate(s1, [0, 1], [scale1, scale2]);
  const rot_1_to_2 = interpolate(s1, [0, 1], [rot1, rot2]);

  const x_2_to_3 = interpolate(s2, [0, 1], [x_1_to_2, x3]);
  const y_2_to_3 = interpolate(s2, [0, 1], [y_1_to_2, y3]);
  const scale_2_to_3 = interpolate(s2, [0, 1], [scale_1_to_2, scale3]);
  const rot_2_to_3 = interpolate(s2, [0, 1], [rot_1_to_2, rot3]);

  const x_3_to_4 = interpolate(s3, [0, 1], [x_2_to_3, x4]);
  const y_3_to_4 = interpolate(s3, [0, 1], [y_2_to_3, y4]);
  const scale_3_to_4 = interpolate(s3, [0, 1], [scale_2_to_3, scale4]);
  const rot_3_to_4 = interpolate(s3, [0, 1], [rot_2_to_3, rot4]);

  const x_4_to_5 = interpolate(s4, [0, 1], [x_3_to_4, x5]);
  const y_4_to_5 = interpolate(s4, [0, 1], [y_3_to_4, y5]);
  const scale_4_to_5 = interpolate(s4, [0, 1], [scale_3_to_4, scale5]);
  const rot_4_to_5 = interpolate(s4, [0, 1], [rot_3_to_4, rot5]);

  const currentX = interpolate(s5, [0, 1], [x_4_to_5, x6]);
  const currentY = interpolate(s5, [0, 1], [y_4_to_5, y6]);
  const currentScale = interpolate(s5, [0, 1], [scale_4_to_5, scale6]);
  const currentRotate = interpolate(s5, [0, 1], [rot_4_to_5, rot6]);

  // Entrance springs for individual components
  const springIn1 = spring({ frame, fps, config: { damping: 12 } });
  const springIn2 = spring({ frame: frame - p2, fps, config: { damping: 11, stiffness: 100 } });
  const springIn3 = spring({ frame: frame - p3, fps, config: { damping: 11, stiffness: 100 } });
  const springIn4 = spring({ frame: frame - p4, fps, config: { damping: 12, stiffness: 90 } });
  const springIn5 = spring({ frame: frame - p5, fps, config: { damping: 11, stiffness: 100 } });
  const springIn6 = spring({ frame: frame - p6, fps, config: { damping: 8, stiffness: 130 } });

  // Dynamic animations per scene

  // Phrase 1 (Fade / Slide up)
  const yOffset1 = interpolate(springIn1, [0, 1], [50, 0], { extrapolateRight: "clamp" });
  const opacity1 = interpolate(springIn1, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const scale1Local = interpolate(springIn1, [0, 1], [0.9, 1], { extrapolateRight: "clamp" });

  // Phrase 2 (Solid box reveals text)
  const bannerScaleX = interpolate(springIn2, [0, 0.6], [0, 1], { extrapolateRight: "clamp" });
  const opacity2 = interpolate(springIn2, [0.3, 0.8], [0, 1], { extrapolateRight: "clamp" });
  const scale2Local = interpolate(springIn2, [0.3, 0.9], [0.85, 1], { extrapolateRight: "clamp" });

  // Phrase 3 (Word parsing & text shake)
  const words3 = phrase3.split(" ");
  const lastWord3 = words3[words3.length - 1] || "";
  const remainingWords3 = words3.slice(0, -1).join(" ") || "";
  const opacity3 = interpolate(springIn3, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const scale3Local = interpolate(springIn3, [0, 1], [0.8, 1], { extrapolateRight: "clamp" });
  const wiggle3 = enableWiggle && frame > p3 && frame < p4
    ? Math.sin((frame - p3) * 0.7) * 4 * interpolate(frame - p3, [0, 20], [1, 0], { extrapolateRight: "clamp" })
    : 0;

  // Phrase 4 (Box scale & reveal)
  const opacity4 = interpolate(springIn4, [0.2, 0.7], [0, 1], { extrapolateRight: "clamp" });
  const scale4LocalX = interpolate(springIn4, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const scale4LocalY = interpolate(springIn4, [0, 1], [0.7, 1], { extrapolateRight: "clamp" });

  // Phrase 5 (Split staggered lines)
  const f5_l1 = frame - p5;
  const f5_l2 = frame - p5 - 6;
  const spring5_l1 = spring({ frame: f5_l1, fps, config: { damping: 12 } });
  const spring5_l2 = spring({ frame: f5_l2, fps, config: { damping: 12 } });
  const opacity5_l1 = interpolate(spring5_l1, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const y5_l1 = interpolate(spring5_l1, [0, 1], [30, 0], { extrapolateRight: "clamp" });
  const opacity5_l2 = interpolate(spring5_l2, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const y5_l2 = interpolate(spring5_l2, [0, 1], [30, 0], { extrapolateRight: "clamp" });

  // Phrase 6 (Slam-down & global camera slam shake)
  const opacity6 = interpolate(springIn6, [0, 0.3], [0, 1], { extrapolateRight: "clamp" });
  const scale6Local = interpolate(springIn6, [0, 1], [3.5, 1], {
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.15, 1, 0.3, 1),
  });
  
  // Viewport-wide heavy camera impact shake when word slams down
  const localF6 = frame - p6;
  const impactShake = enableWiggle && localF6 > 8 && localF6 < 28
    ? Math.sin(localF6 * 1.6) * 12 * interpolate(localF6, [8, 28], [1, 0], { extrapolateRight: "clamp" })
    : 0;

  const cameraShakeX = impactShake;
  const cameraShakeY = impactShake * 0.6; // subtle diagonal displacement

  // Helper helper function to return absolute center wrappers
  const phraseWrapperStyle = (x: number, y: number): React.CSSProperties => ({
    position: "absolute",
    left: "50%",
    top: "50%",
    transform: `translate(-50%, -50%) translate(${x}px, ${y}px)`,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    width: "max-content",
    whiteSpace: "nowrap",
    transition: "none",
  });

  // Camera container transform calculation
  const containerStyle: React.CSSProperties = {
    position: "absolute",
    width: "100%",
    height: "100%",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    transform: `scale(${1 / currentScale}) rotate(${-currentRotate}deg) translate(${-currentX + cameraShakeX}px, ${-currentY + cameraShakeY}px)`,
    transformOrigin: "center center",
    transition: "none",
  };

  // Bottom progress bar
  const progressPercent = interpolate(frame, [0, durationInFrames], [0, 100], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Dynamic Camera viewport wrapper */}
      <div style={containerStyle}>
        {/* Dynamic coordinate space grid */}
        <GridBackground width={width} height={height} gridColor={gridColor} />

        {/* Ambient atmospheric bokeh / neon spheres */}
        <GlowBlob x={x2} y={y2} size={width * 0.45} color={accentColor} opacity={0.2} />
        <GlowBlob x={x5} y={y5} size={width * 0.55} color={accentColor} opacity={0.15} />

        {/* PHRASE 1 */}
        <div style={phraseWrapperStyle(x1, y1)}>
          <div
            style={{
              fontFamily: interFamily,
              fontSize: height * 0.065 * fontSizeMultiplier,
              fontWeight: 500,
              color: textColor,
              opacity: opacity1,
              transform: `translateY(${yOffset1}px) scale(${scale1Local})`,
              letterSpacing: "4px",
              textTransform: "uppercase",
              transition: "none",
            }}
          >
            {phrase1}
          </div>
        </div>

        {/* PHRASE 2 */}
        <div style={phraseWrapperStyle(x2, y2)}>
          <div
            style={{
              position: "relative",
              padding: `${height * 0.015}px ${height * 0.04}px`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
            }}
          >
            <div
              style={{
                position: "absolute",
                top: 0,
                bottom: 0,
                left: 0,
                right: 0,
                backgroundColor: accentColor,
                transform: `scaleX(${bannerScaleX})`,
                transformOrigin: "left center",
                borderRadius: "8px",
                transition: "none",
              }}
            />
            <div
              style={{
                position: "relative",
                fontFamily: spaceGroteskFamily,
                fontSize: height * 0.08 * fontSizeMultiplier,
                fontWeight: 900,
                color: backgroundColor,
                opacity: opacity2,
                transform: `scale(${scale2Local})`,
                letterSpacing: "2px",
                textTransform: "uppercase",
                transition: "none",
              }}
            >
              {phrase2}
            </div>
          </div>
        </div>

        {/* PHRASE 3 */}
        <div style={phraseWrapperStyle(x3, y3)}>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              opacity: opacity3,
              transform: `scale(${scale3Local}) translateX(${wiggle3}px)`,
              transition: "none",
            }}
          >
            <div
              style={{
                fontFamily: interFamily,
                fontSize: height * 0.04 * fontSizeMultiplier,
                fontWeight: 700,
                color: textColor,
                letterSpacing: "6px",
                textTransform: "uppercase",
                opacity: 0.85,
                transition: "none",
              }}
            >
              {remainingWords3}
            </div>
            <div
              style={{
                fontFamily: spaceGroteskFamily,
                fontSize: height * 0.09 * fontSizeMultiplier,
                fontWeight: 900,
                color: accentColor,
                letterSpacing: "3px",
                textTransform: "uppercase",
                textShadow: `0 0 25px ${accentColor}44`,
                transition: "none",
              }}
            >
              {lastWord3}
            </div>
          </div>
        </div>

        {/* PHRASE 4 */}
        <div style={phraseWrapperStyle(x4, y4)}>
          <div
            style={{
              border: `3px solid ${textColor}`,
              borderRadius: "50px",
              padding: `${height * 0.012}px ${height * 0.04}px`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: opacity4,
              transform: `scaleX(${scale4LocalX})`,
              transition: "none",
            }}
          >
            <div
              style={{
                fontFamily: interFamily,
                fontSize: height * 0.045 * fontSizeMultiplier,
                fontWeight: 700,
                color: textColor,
                letterSpacing: "6px",
                textTransform: "uppercase",
                transform: `scaleY(${scale4LocalY})`,
                transition: "none",
              }}
            >
              {phrase4}
            </div>
          </div>
        </div>

        {/* PHRASE 5 */}
        <div style={phraseWrapperStyle(x5, y5)}>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transition: "none",
            }}
          >
            <div
              style={{
                fontFamily: spaceGroteskFamily,
                fontSize: height * 0.08 * fontSizeMultiplier,
                fontWeight: 800,
                color: textColor,
                opacity: opacity5_l1,
                transform: `translateY(${y5_l1}px)`,
                letterSpacing: "3px",
                textTransform: "uppercase",
                textAlign: "center",
                transition: "none",
              }}
            >
              {phrase5Line1}
            </div>
            <div
              style={{
                fontFamily: spaceGroteskFamily,
                fontSize: height * 0.09 * fontSizeMultiplier,
                fontWeight: 900,
                color: accentColor,
                opacity: opacity5_l2,
                transform: `translateY(${y5_l2}px)`,
                letterSpacing: "4px",
                textTransform: "uppercase",
                textAlign: "center",
                marginTop: "10px",
                textShadow: `0 0 30px ${accentColor}33`,
                transition: "none",
              }}
            >
              {phrase5Line2}
            </div>
          </div>
        </div>

        {/* PHRASE 6 */}
        <div style={phraseWrapperStyle(x6, y6)}>
          <div
            style={{
              fontFamily: spaceGroteskFamily,
              fontSize: height * 0.16 * fontSizeMultiplier,
              fontWeight: 900,
              color: textColor,
              opacity: opacity6,
              transform: `scale(${scale6Local})`,
              letterSpacing: "2px",
              textTransform: "uppercase",
              textAlign: "center",
              textShadow: `0 10px 40px rgba(0,0,0,0.8), 0 0 45px ${accentColor}25`,
              transition: "none",
            }}
          >
            {phrase6}
          </div>
        </div>
      </div>

      {/* Screen bottom subtle timeline indicator */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          height: "6px",
          width: `${progressPercent}%`,
          backgroundColor: accentColor,
          boxShadow: `0 0 10px ${accentColor}`,
          opacity: 0.8,
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default KineticHookText;